using System;
using UnityEngine;

namespace Game.Levels
{
    [Serializable]
    public struct RingSpec
    {
        public Vector3 Position;
        [Tooltip("Facing (deg around Y): the plane flies through along this heading.")]
        public float Yaw;
        public float Radius;
    }

    /// <summary>
    /// One level (SPEC §2): where it starts, what the mission is, its star goals and the mission items to place.
    /// Generated by Tools/Game/Build Levels (LevelBuilder) from a table in code; tune here or there.
    /// </summary>
    [CreateAssetMenu(menuName = "Game/Configs/Level", fileName = "Level")]
    public sealed class LevelConfig : ScriptableObject
    {
        [SerializeField] private string _title = "Level";
        [SerializeField] private string _room = "Living room";
        [SerializeField] private MissionType _mission = MissionType.Airtime;
        [Tooltip("Shown before the throw and on the HUD, e.g. \"Collect the gems\".")]
        [SerializeField] private string _objective = "";

        [Header("Start")]
        [Tooltip("Plane position on the shelf / pad.")]
        [SerializeField] private Vector3 _start;
        [SerializeField] private float _startYaw;
        [Tooltip("Off: launch from the living-room shelf. On: a stack of books is placed under the start point.")]
        [SerializeField] private bool _bookStack = true;
        [Tooltip("Height (m) of the surface the book stack stands on (0 = floor).")]
        [SerializeField] private float _surfaceHeight;

        [Header("Goals")]
        [Tooltip("Star thresholds; meaning depends on the mission (see MissionTracker).")]
        [SerializeField] private float[] _stars = { 10f, 15f, 20f };

        [Header("Mission items")]
        [SerializeField] private Vector3[] _gems = Array.Empty<Vector3>();
        [SerializeField] private RingSpec[] _rings = Array.Empty<RingSpec>();
        [Tooltip("Land: centre of the target's top surface.")]
        [SerializeField] private Vector3 _landCenter;
        [Tooltip("Land: target size on the surface (x, z), metres.")]
        [SerializeField] private Vector2 _landSize = new Vector2(1.6f, 1.6f);
        [Tooltip("ReachRoom: the room to fly into (world bounds).")]
        [SerializeField] private Bounds _targetRoom;

        public string Title => _title;
        public string Room => _room;
        public MissionType Mission => _mission;
        public string Objective => _objective;
        public Vector3 Start => _start;
        public float StartYaw => _startYaw;
        public bool BookStack => _bookStack;
        public float SurfaceHeight => _surfaceHeight;
        public float[] Stars => _stars;
        public Vector3[] Gems => _gems;
        public RingSpec[] Rings => _rings;
        public Vector3 LandCenter => _landCenter;
        public Vector2 LandSize => _landSize;
        public Bounds TargetRoom => _targetRoom;

#if UNITY_EDITOR
        /// <summary>Editor-only setter used by LevelBuilder.</summary>
        public void Define(string title, string room, MissionType mission, string objective, Vector3 start, float startYaw,
            bool bookStack, float surfaceHeight, float[] stars, Vector3[] gems, RingSpec[] rings, Vector3 landCenter,
            Vector2 landSize, Bounds targetRoom)
        {
            _title = title;
            _room = room;
            _mission = mission;
            _objective = objective;
            _start = start;
            _startYaw = startYaw;
            _bookStack = bookStack;
            _surfaceHeight = surfaceHeight;
            _stars = stars;
            _gems = gems ?? Array.Empty<Vector3>();
            _rings = rings ?? Array.Empty<RingSpec>();
            _landCenter = landCenter;
            _landSize = landSize;
            _targetRoom = targetRoom;
        }
#endif
    }
}
